	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void valueStoreOccupiedBytesWaitsForExclusiveNativeRemap(@TempDir Path dataDir) throws Exception {
		try (CapturedStores stores = stores(dataDir)) {
			seed(stores.store());

			BarrierRead<Long> blockedRead = whileWriteLocked(stores.values().getTxnManager().lockManager(),
					stores.values()::occupiedBytes);
			long whileOwningBarrier = whileOwningWriteLock(stores.values().getTxnManager().lockManager(),
					stores.values()::occupiedBytes);

			assertTrue(blockedRead.workerStarted(),
					"the ValueStore read reached the actual method while the barrier was held");
			assertTrue(blockedRead.result() > 0,
					"the ValueStore occupied-byte read returns the initialized native map high-water");
			assertEquals(blockedRead.result(), whileOwningBarrier,
					"a native remap owner can inspect ValueStore occupancy without reacquiring its own barrier");
			assertFalse(blockedRead.completedWhileLocked(),
					"ValueStore occupancy waits for the foreign exclusive barrier");
		}
	}

