	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void usedIdFilterWaitsForExclusiveNativeRemap(@TempDir Path dataDir) throws Exception {
		try (CapturedStores stores = stores(dataDir)) {
			Statement used = statement("used");
			try (SailSink sink = stores.store().getExplicitSailSource().sink(IsolationLevels.NONE)) {
				sink.approve(used);
				sink.setNamespace("native-remap", "urn:native-remap:namespace");
				sink.flush();
			}
			Resource unusedValue = VF.createIRI("urn:native-remap:dictionary-only");
			stores.values().startTransaction(true);
			long unusedId;
			try {
				unusedId = stores.values().getId(unusedValue, true);
				stores.values().commit();
			} catch (Exception failure) {
				stores.values().rollback();
				throw failure;
			}

			long usedId = stores.values().getId(used.getSubject());
			assertNotEquals(-1L, usedId, "the used test identifier must be present in the native ValueStore");
			assertNotEquals(-1L, unusedId, "the dictionary-only test identifier must be present in the ValueStore");
			List<Long> candidates = new ArrayList<>(List.of(usedId, unusedId));

			BarrierRead<List<Long>> blockedRead = whileWriteLocked(stores.triples().getTxnManager().lockManager(),
					() -> {
						stores.triples().filterUsedIds(candidates);
						return List.copyOf(candidates);
					});

			assertTrue(blockedRead.workerStarted(),
					"the ID filter reached the actual method while the barrier was held");
			assertFalse(blockedRead.completedWhileLocked(), "the ID filter waits for the foreign exclusive barrier");
			assertEquals(List.of(unusedId), blockedRead.result(),
					"the native filter removes the committed subject and preserves the dictionary-only subject");
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void interruptedNamespaceSnapshotReleasesForeignMetadataReadAdmission(@TempDir Path dataDir) throws Exception {
		try (CapturedStores stores = stores(dataDir)) {
			seed(stores.store());
			CountDownLatch entered = stores.triples().expectNamespaceRead();
			AtomicReference<Map<String, String>> result = new AtomicReference<>();
			AtomicReference<Throwable> failure = new AtomicReference<>();
			AtomicBoolean interruptRestored = new AtomicBoolean();
			Thread reader = new Thread(() -> {
				try {
					result.set(stores.triples().readNamespaceSnapshot());
				} catch (Throwable caught) {
					failure.set(caught);
					interruptRestored.set(Thread.currentThread().isInterrupted());
				}
			}, "native-remap-interrupted-namespace-reader");

			var lockManager = stores.triples().getTxnManager().lockManager();
			long stamp = lockManager.writeLock();
			boolean reachedRead = false;
			boolean stoppedBeforeRelease = false;
			try {
				reader.start();
				reachedRead = entered.await(2, TimeUnit.SECONDS);
				reader.interrupt();
				reader.join(2_000);
				stoppedBeforeRelease = !reader.isAlive();
			} finally {
				lockManager.unlockWrite(stamp);
				reader.interrupt();
				reader.join(2_000);
			}

			assertTrue(reachedRead, "the foreign snapshot call entered before its native read barrier was interrupted");
			assertTrue(stoppedBeforeRelease,
					"interruption must cancel the blocked metadata read before writer release");
			assertFalse(reader.isAlive(), "the interrupted reader must be joined after releasing the writer barrier");
			assertNull(result.get(), "a cancelled namespace snapshot must not publish a partial result");
			assertNotNull(failure.get(), "the cancelled metadata read must report its interrupted lock acquisition");
			assertTrue(failure.get() instanceof IOException || failure.get() instanceof SailException,
					"interrupted metadata admission reports its supported I/O or Sail failure: " + failure.get());
			assertTrue(failure.get().getCause() instanceof InterruptedException,
					"the original interrupt must remain the metadata-read cause");
			assertTrue(interruptRestored.get(), "the interrupted reader must restore its interrupt status");
			assertEquals(Map.of("native-remap", "urn:native-remap:namespace"),
					stores.triples().readNamespaceSnapshot(),
					"a later namespace read must acquire and release the barrier normally");
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void rejectedWriteReacquisitionAndInvalidStampPreserveMetadataOwner(@TempDir Path dataDir) throws Exception {
		try (CapturedStores stores = stores(dataDir)) {
			seed(stores.store());
			var lockManager = stores.triples().getTxnManager().lockManager();
			long stamp = lockManager.writeLock();
			long occupiedBytes;
			try {
				assertEquals(0L, lockManager.tryWriteLock(),
						"a write owner cannot reacquire its non-reentrant native barrier");
				assertThrows(IllegalMonitorStateException.class,
						() -> lockManager.unlockWrite(StampedLongAdderLockManager.READ_LOCK_STAMP),
						"a read stamp must be rejected as a write unlock");
				occupiedBytes = stores.triples().occupiedBytes();
			} finally {
				lockManager.unlockWrite(stamp);
			}
			assertTrue(occupiedBytes > 0,
					"the valid write owner remains recognized after rejected reacquisition and invalid unlock");
			assertTrue(stores.triples().occupiedBytes() > 0,
					"the original valid stamp releases the barrier for later metadata readers");
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void freshNamespaceAndUsedIdReadsFollowCommittedCleanupFailure(@TempDir Path dataDir) throws Exception {
		try (CapturedStores stores = stores(dataDir)) {
			seed(stores.store());
			ProbeTripleStore triples = stores.triples();
			Statement initial = statement("used");
			long initialUsedId = stores.values().getId(initial.getSubject());
			assertNotEquals(-1L, initialUsedId, "the seeded statement's dictionary identifier must be present");
			Resource unusedValue = VF.createIRI("urn:native-remap:dictionary-only");
			stores.values().startTransaction(true);
			long unusedId;
			try {
				unusedId = stores.values().getId(unusedValue, true);
				stores.values().commit();
			} catch (Exception failure) {
				stores.values().rollback();
				throw failure;
			}

			assertEquals(Map.of("native-remap", "urn:native-remap:namespace"), triples.readNamespaceSnapshot());
			List<Long> primingIds = new ArrayList<>(List.of(initialUsedId, unusedId));
			triples.filterUsedIds(primingIds);
			assertEquals(List.of(unusedId), primingIds,
					"the first namespace and ID reads exercise the ordinary pooled-reader path");

			IOException cleanupFailure = new IOException("injected cleanup after successful native commit");
			long generationBeforeCommit = triples.getNativeCommitGeneration();
			triples.failAfterNextSuccessfulCommit(cleanupFailure);
			Statement committed = statement("committed-after-cleanup");
			Throwable reportedFailure = null;
			try {
				try (SailSink sink = stores.store().getExplicitSailSource().sink(IsolationLevels.NONE)) {
					sink.approve(committed);
					sink.setNamespace("after-cleanup", "urn:native-remap:committed");
					sink.flush();
				}
			} catch (Throwable failure) {
				reportedFailure = failure;
			}

			assertNotNull(reportedFailure, "the injected post-commit cleanup failure must reach the sink caller");
			assertTrue(causeChainContainsIdentity(reportedFailure, cleanupFailure),
					"the exact cleanup marker must remain visible after the authoritative native commit");
			assertTrue(triples.getNativeCommitGeneration() > generationBeforeCommit,
					"the native commit must be confirmed before the cleanup failure is injected");

			assertEquals(Map.of("native-remap", "urn:native-remap:namespace", "after-cleanup",
					"urn:native-remap:committed"), triples.readNamespaceSnapshot(),
					"a pooled namespace snapshot must renew after the committed cleanup failure");
			long committedId = stores.values().getId(committed.getSubject());
			List<Long> currentIds = new ArrayList<>(List.of(initialUsedId, committedId, unusedId));
			triples.filterUsedIds(currentIds);
			assertEquals(List.of(unusedId), currentIds,
					"a pooled ID-filter reader must renew and see the committed statement index");
		}
	}

	private static boolean causeChainContainsIdentity(Throwable failure, Throwable expected) {
		for (Throwable current = failure; current != null; current = current.getCause()) {
			if (current == expected) {
				return true;
			}
		}
		return false;
	}

	private static CapturedStores stores(Path dataDir) throws Exception {
		AtomicReference<ValueStore> values = new AtomicReference<>();
		AtomicReference<ProbeTripleStore> triples = new AtomicReference<>();
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setValueDBSize(16L * 1024 * 1024)
				.setTripleDBSize(16L * 1024 * 1024);
		LmdbSailStore store = new LmdbSailStore(dataDir.toFile(), new StoreProperties(dataDir.toFile()), config, false,
				(valueDir, properties, valueConfig) -> {
					ValueStore valueStore = new ValueStore(valueDir, properties, valueConfig);
					values.set(valueStore);
					return valueStore;
				}, (tripleDir, properties, tripleConfig, valueStore) -> {
					ProbeTripleStore tripleStore = new ProbeTripleStore(tripleDir, properties, tripleConfig,
							valueStore);
					triples.set(tripleStore);
					return tripleStore;
				});
		return new CapturedStores(store, values.get(), triples.get());
	}

	private static void seed(LmdbSailStore store) throws Exception {
		try (SailSink sink = store.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			sink.approve(statement("used"));
			sink.setNamespace("native-remap", "urn:native-remap:namespace");
			sink.flush();
		}
	}

	private static Statement statement(String localName) {
		Resource subject = VF.createIRI("urn:native-remap:", localName);
		IRI predicate = VF.createIRI("urn:native-remap:predicate");
		return VF.createStatement(subject, predicate, VF.createLiteral(localName));
	}

	private static <T> BarrierRead<T> whileWriteLocked(StampedLongAdderLockManager lockManager, Callable<T> read)
			throws Exception {
		long stamp = lockManager.writeLock();
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CountDownLatch started = new CountDownLatch(1);
		Future<T> future = executor.submit(() -> {
			started.countDown();
			return read.call();
		});
		boolean workerStarted = false;
		boolean completedWhileLocked = false;
		try {
			try {
				workerStarted = started.await(2, TimeUnit.SECONDS);
				if (workerStarted) {
					try {
						future.get(200, TimeUnit.MILLISECONDS);
						completedWhileLocked = true;
					} catch (TimeoutException expectedWhileBlocked) {
						// The actual assertion is delayed until after releasing and joining the worker.
					} catch (ExecutionException completedWithFailure) {
						completedWhileLocked = true;
					}
				}
			} finally {
				lockManager.unlockWrite(stamp);
			}
			T result = future.get(3, TimeUnit.SECONDS);
			return new BarrierRead<>(workerStarted, completedWhileLocked, result);
		} finally {
			executor.shutdownNow();
			executor.awaitTermination(2, TimeUnit.SECONDS);
		}
	}

	private record BarrierRead<T> (boolean workerStarted, boolean completedWhileLocked, T result) {
	}

	private static <T> T whileOwningWriteLock(StampedLongAdderLockManager lockManager, Callable<T> read)
			throws Exception {
		long stamp = lockManager.writeLock();
		try {
			return read.call();
		} finally {
			lockManager.unlockWrite(stamp);
		}
	}

	private record CapturedStores(LmdbSailStore store, ValueStore values, ProbeTripleStore triples)
			implements AutoCloseable {
		@Override
		public void close() throws Exception {
			store.close();
		}
	}

	private static final class ProbeTripleStore extends TripleStore {
		private final AtomicReference<CountDownLatch> namespaceReadEntered = new AtomicReference<>();
		private final AtomicReference<IOException> failureAfterSuccessfulCommit = new AtomicReference<>();

		private ProbeTripleStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				ValueStore valueStore)
				throws IOException, SailException {
			super(directory, properties, config, valueStore);
		}

		CountDownLatch expectNamespaceRead() {
			CountDownLatch entered = new CountDownLatch(1);
			namespaceReadEntered.set(entered);
			return entered;
		}

		void failAfterNextSuccessfulCommit(IOException failure) {
			failureAfterSuccessfulCommit.set(failure);
		}

		@Override
		Map<String, String> readNamespaceSnapshot() throws IOException {
			CountDownLatch entered = namespaceReadEntered.get();
			if (entered != null) {
				entered.countDown();
			}
			return super.readNamespaceSnapshot();
		}

		@Override
		public void commit() throws IOException {
			super.commit();
			IOException failure = failureAfterSuccessfulCommit.getAndSet(null);
			if (failure != null) {
				throw failure;
			}
		}
	}
